 * I2C WHO_AM_I Read Example for NXP MCXC144 (Cortex-M0+)
 *
 * Reads register 0x75 from an I2C sensor at 7-bit address 0x68.
 * Uses I2C0 on PTC8 (SCL) and PTC9 (SDA) at 100 kHz.
 * Only MCUXpresso SDK driver headers are included; no board files.
 */

#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_i2c.h"

/* Sensor I2C address (7-bit) and register to read */
#define SENSOR_I2C_ADDR 0x68U
#define WHO_AM_I_REG    0x75U

/* Desired I2C baud rate in Hz */
#define I2C_BAUDRATE    100000U

/* Result buffer */
static uint8_t who_am_i_value = 0U;

/* ------------------------------------------------------------------------- */
/* Pin mux configuration                                                     */
/* ------------------------------------------------------------------------- */
static void init_pins(void)
{
    /* Enable clock for PORTC */
    CLOCK_EnableClock(kCLOCK_PortC);

    /* Configure PTC8 as I2C0_SCL (ALT2) and PTC9 as I2C0_SDA (ALT2) */
    PORT_SetPinMux(PORTC, 8U, kPORT_MuxAlt2);
    PORT_SetPinMux(PORTC, 9U, kPORT_MuxAlt2);
}

/* ------------------------------------------------------------------------- */
/* Clock configuration                                                       */
/* ------------------------------------------------------------------------- */
static void init_clocks(void)
{
    /* Enable clock for I2C0 module */
    CLOCK_EnableClock(kCLOCK_I2c0);

    /* On MCXC144, the I2C0 clock source is the bus clock.
     * The bus clock is already configured by default system clock setup.
     * No further clock configuration is needed for this simple example.
     */
}

/* ------------------------------------------------------------------------- */
/* I2C master initialization                                                  */
/* ------------------------------------------------------------------------- */
static void init_i2c(I2C_Type *base)
{
    i2c_master_config_t masterConfig;

    /* Get default configuration */
    I2C_MasterGetDefaultConfig(&masterConfig);

    /* Set baud rate */
    masterConfig.baudRate_Bps = I2C_BAUDRATE;

    /* Initialize I2C master with bus clock frequency */
    I2C_MasterInit(base, &masterConfig, CLOCK_GetFreq(kCLOCK_BusClk));
}

/* ------------------------------------------------------------------------- */
/* Read a single register from the sensor via I2C                            */
/* ------------------------------------------------------------------------- */
static int read_register(I2C_Type *base, uint8_t devAddr, uint8_t regAddr,
                         uint8_t *rxData)
{
    status_t status;
    i2c_master_transfer_t transfer;

    /* Prepare combined transfer: write register address, then read one byte */
    transfer.slaveAddress   = devAddr;
    transfer.direction      = kI2C_Read;
    transfer.subaddress     = (uint32_t)regAddr;
    transfer.subaddressSize = 1U;          /* one-byte register address */
    transfer.data           = rxData;
    transfer.dataSize       = 1U;
    transfer.flags          = kI2C_TransferDefaultFlag; /* generates repeated start */

    /* Perform blocking transfer */
    status = I2C_MasterTransferBlocking(base, &transfer);

    return (int)status;   /* 0 = success, otherwise error code */
}

/* ------------------------------------------------------------------------- */
/* Main application                                                           */
/* ------------------------------------------------------------------------- */
int main(void)
{
    int error;

    /* Configure pins and clocks */
    init_pins();
    init_clocks();

    /* Initialize I2C0 */
    init_i2c(I2C0);

    /* Read WHO_AM_I register */
    error = read_register(I2C0, SENSOR_I2C_ADDR, WHO_AM_I_REG, &who_am_i_value);

    if (error != kStatus_Success)
    {
        /* Communication error – infinite loop with optional debug action */
        while (1)
        {
            /* Place breakpoint here or toggle LED for debug */
            __NOP();
        }
    }

    /* WHO_AM_I value is now stored in who_am_i_value.
     * Continue with application logic...
     */

    while (1)
    {
        /* Idle loop */
    }
}

/*
 * Bare-metal C application for NXP MCXC144 (Cortex-M0+)
 * using MCUXpresso SDK.
 *
 * - PIT channel 0 generates interrupts every 10 ms.
 * - In the ISR, digital input PTC3 is sampled and stored.
 * - A volatile flag signals the main loop that a new sample is ready.
 * - Main loop disables interrupts while reading the flag/sample to avoid races,
 *   then toggles PTE24 (LED) if the pin was high.
 *
 * Includes only MCUXpresso SDK driver headers and relies on the default
 * system clock (48 MHz bus clock).
 */

#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_pit.h"

/* --------------------------------------------------------------------------
 * Shared data between ISR and main loop
 * -------------------------------------------------------------------------- */
static volatile uint8_t g_sampleReady = 0;   /* 1 = new sample available */
static volatile uint32_t g_sampleValue = 0;  /* sampled PTC3 value (0/1) */

/* --------------------------------------------------------------------------
 * PIT interrupt handler
 * -------------------------------------------------------------------------- */
void PIT_IRQHandler(void)
{
    /* Clear the channel 0 interrupt flag */
    PIT_ClearStatusFlags(PIT, kPIT_Chnl_0, kPIT_TimerFlag);

    /* Read the digital input on PTC3 */
    g_sampleValue = GPIO_PinRead(GPIOC, 3);

    /* Signal main loop that a sample is ready */
    g_sampleReady = 1;

    /* Note: No additional synchronization needed here because the write to
     * g_sampleValue completes before the write to g_sampleReady (the compiler
     * does not reorder volatile accesses). The main loop will disable
     * interrupts while reading both variables, so this ISR cannot preempt
     * that critical section. */
}

/* --------------------------------------------------------------------------
 * Pin and peripheral initialization
 * -------------------------------------------------------------------------- */
static void init_pins(void)
{
    /* Enable clock gates for PORT C (PTC3) and PORT E (PTE24) */
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_PortE);

    /* PTC3 as GPIO input (no pull, no filter) */
    PORT_SetPinMux(PORTC, 3, kPORT_MuxAsGpio);
    gpio_pin_config_t inputCfg = {
        .pinDirection = kGPIO_DigitalInput,
        .outputLogic  = 0    /* not used for input */
    };
    GPIO_PinInit(GPIOC, 3, &inputCfg);

    /* PTE24 as GPIO output (LED) */
    PORT_SetPinMux(PORTE, 24, kPORT_MuxAsGpio);
    gpio_pin_config_t outputCfg = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = 0
    };
    GPIO_PinInit(GPIOE, 24, &outputCfg);
}

static void init_pit(void)
{
    /* Enable PIT clock gate */
    CLOCK_EnableClock(kCLOCK_Pit);

    /* PIT configuration (using default) */
    pit_config_t pitConfig;
    PIT_GetDefaultConfig(&pitConfig);
    PIT_Init(PIT, &pitConfig);

    /* Set timer period for channel 0: 10 ms @ 48 MHz bus clock */
    /* Period in counts = (10 ms / 1 s) * 48e6 = 480000 */
    PIT_SetTimerPeriod(PIT, kPIT_Chnl_0, 480000 - 1);

    /* Enable interrupt for channel 0 */
    PIT_EnableInterrupts(PIT, kPIT_Chnl_0, kPIT_TimerInterruptEnable);

    /* Enable PIT interrupt in the NVIC */
    NVIC_EnableIRQ(PIT_IRQn);

    /* Start the timer */
    PIT_StartTimer(PIT, kPIT_Chnl_0);
}

/* --------------------------------------------------------------------------
 * Main application
 * -------------------------------------------------------------------------- */
int main(void)
{
    /* Disable global interrupts until init is complete */
    __disable_irq();

    /* Initialize pins and PIT */
    init_pins();
    init_pit();

    /* Enable global interrupts (PIT will start firing after this) */
    __enable_irq();

    while (1)
    {
        /* Critical section: read flag and sample atomically by disabling
         * interrupts. This prevents the ISR from modifying the shared
         * variables during the read. */
        __disable_irq();
        uint8_t ready = g_sampleReady;
        uint32_t sample = g_sampleValue;
        __enable_irq();

        if (ready)
        {
            /* Process the sample: if pin was high, toggle the LED */
            if (sample)
            {
                GPIO_PortToggle(GPIOE, 1u << 24);
            }

            /* Clear the flag – note that we do it outside the critical
             * section because the flag is only written by the ISR when
             * it sets it to 1. The main loop clears it to 0, and this
             * write is atomic. A new ISR could set it again immediately,
             * but that is safe because we have already processed the
             * current sample. */
            g_sampleReady = 0;
        }

        /* Optionally add a small WFI or delay to reduce power consumption */
        __WFI();
    }
}

