/*
 * Bare-metal MCXC144 SPI0 master example using MCUXpresso SDK.
 * Sends {0x9F, 0x00} and stores the two received bytes.
 * All pin/clock/peripheral setup is done via SDK driver APIs.
 */

#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_spi.h"

/* Store the two received bytes */
static uint8_t receivedBytes[2] = {0};

/* Pin definitions */
#define CS_GPIO       GPIOC
#define CS_PIN        5
#define MISO_PIN      4
#define SCK_PIN       6
#define MOSI_PIN      7

/* SPI speed */
#define SPI_BAUDRATE  1000000U

/* Clock gating names for MCXC144 */
#define SPI0_CLOCK    kCLOCK_Spi0
#define PORTC_CLOCK   kCLOCK_PortC

int main(void)
{
    status_t status;

    /* ------------------------------------------------------------------
     * 1. Enable clocks for PORT C and SPI0
     * ----------------------------------------------------------------*/
    CLOCK_EnableClock(PORTC_CLOCK);
    CLOCK_EnableClock(SPI0_CLOCK);

    /* ------------------------------------------------------------------
     * 2. Configure pins
     *    PTC6 = SCK,  PTC7 = MOSI, PTC4 = MISO  (all ALT2)
     *    PTC5 = CS (GPIO output)
     * ----------------------------------------------------------------*/
    PORT_SetPinMux(PORTC, SCK_PIN,  kPORT_MuxAlt2);
    PORT_SetPinMux(PORTC, MOSI_PIN, kPORT_MuxAlt2);
    PORT_SetPinMux(PORTC, MISO_PIN, kPORT_MuxAlt2);

    /* CS pin as GPIO output, initially high (inactive) */
    PORT_SetPinMux(PORTC, CS_PIN, kPORT_MuxAsGpio);
    gpio_pin_config_t csConfig = {kGPIO_DigitalOutput, 1};
    GPIO_PinInit(CS_GPIO, CS_PIN, &csConfig);

    /* ------------------------------------------------------------------
     * 3. Initialise SPI0 as master, CPOL=0, CPHA=0, 8-bit, 1 MHz
     * ----------------------------------------------------------------*/
    spi_master_config_t spiConfig;
    SPI_MasterGetDefaultConfig(&spiConfig);
    spiConfig.baudRate_Bps = SPI_BAUDRATE;
    spiConfig.polarity     = kSPI_ClockPolarityActiveHigh;   /* CPOL = 0 */
    spiConfig.phase        = kSPI_ClockPhaseFirstEdge;       /* CPHA = 0 */
    spiConfig.dataWidth    = 8;                              /* 8-bit frame */

    /* No manual chip select for SPI hardware – we control CS via GPIO */
    spiConfig.sselNum        = kSPI_Ssel0;          /* not used */
    spiConfig.sselPol        = kSPI_SselActiveHighLow; /* not used */
    spiConfig.isMaster       = true;

    status = SPI_MasterInit(SPI0, &spiConfig, CLOCK_GetFreq(kCLOCK_CoreSysClk));
    if (status != kStatus_Success)
    {
        /* Initialisation failed – hang forever */
        while (1) {}
    }

    /* ------------------------------------------------------------------
     * 4. Perform the transfer: assert CS, send {0x9F,0x00}, receive 2 bytes
     * ----------------------------------------------------------------*/
    static const uint8_t txData[2] = {0x9F, 0x00};
    uint8_t rxData[2] = {0};

    /* Assert CS (active low) */
    GPIO_PinWrite(CS_GPIO, CS_PIN, 0);

    /* Blocking full-duplex transfer */
    status = SPI_WriteReadBlocking(SPI0, &txData[0], &rxData[0], 2);

    /* Deassert CS */
    GPIO_PinWrite(CS_GPIO, CS_PIN, 1);

    if (status == kStatus_Success)
    {
        /* Store received bytes */
        receivedBytes[0] = rxData[0];
        receivedBytes[1] = rxData[1];
    }
    else
    {
        /* Transfer failed – clear received bytes */
        receivedBytes[0] = 0;
        receivedBytes[1] = 0;
    }

    /* ------------------------------------------------------------------
     * 5. Infinite loop (application would continue here)
     * ----------------------------------------------------------------*/
    while (1) {}
}

