/*
 * MCXC144 UART0 "Hello\r\n" loop
 * Pin mux: PTA1 (RX), PTA2 (TX)
 * Baud: 115200 8N1
 * 1-second software delay using busy loop
 * Uses MCUXpresso SDK driver headers only.
 */

#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_uart.h"

/* Pin multiplexing alternatives (UART0 on PORTA) */
#define UART0_RX_PIN   1
#define UART0_TX_PIN   2
#define UART0_PORT     PORTA
#define UART0_RX_ALT   kPORT_MuxAlt2
#define UART0_TX_ALT   kPORT_MuxAlt2

/* Approximate busy‑loop count for 1 s delay at 48 MHz core */
#define DELAY_1S_COUNT 16000000U

/*---------------------------------------------------------------------------*/
/* One‑second delay using a simple volatile busy loop                        */
static void delay_1s(void)
{
    volatile uint32_t count = DELAY_1S_COUNT;
    while (count--)
    {
        __NOP();
    }
}

/*---------------------------------------------------------------------------*/
/* Main application                                                          */
int main(void)
{
    /* Enable clock gates for UART0 and PORTA */
    CLOCK_EnableClock(kCLOCK_Uart0);
    CLOCK_EnableClock(kCLOCK_PortA);

    /* Configure pin mux for UART0 RX and TX on PORTA */
    PORT_SetPinMux(UART0_PORT, UART0_RX_PIN, UART0_RX_ALT);
    PORT_SetPinMux(UART0_PORT, UART0_TX_PIN, UART0_TX_ALT);

    /* Initialize UART0 */
    uart_config_t config;
    UART_GetDefaultConfig(&config);
    config.baudRate_Bps = 115200;
    config.enableTx     = true;
    config.enableRx     = true;          /* optional, both enabled */
    config.parityMode   = kUART_ParityDisabled;
    config.stopBitCount = kUART_OneStopBit;

    uint32_t uartSourceClock = CLOCK_GetFreq(kCLOCK_CoreSysClk);
    UART_Init(UART0, &config, uartSourceClock);

    /* Transmit "Hello\r\n" every second */
    while (1)
    {
        UART_WriteBlocking(UART0, (const uint8_t *)"Hello\r\n", 7);
        delay_1s();
    }
}

