/*
 * Bare-metal eDMA memory-to-memory copy for NXP i.MX RT1170
 * MCUXpresso SDK – no board files, no CMSIS device headers beyond SDK.
 * Copies 512 bytes from source to destination via DMA0 channel 0.
 * Fills source with (index & 0xFF), waits for completion, then verifies.
 */

#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_edma.h"
#include "fsl_dmamux.h"

/* ── Buffers (aligned to 32 bytes for best DMA performance) ─────────── */
AT_NONCACHEABLE_SECTION_ALIGN(static uint8_t src[512], 32);
AT_NONCACHEABLE_SECTION_ALIGN(static uint8_t dst[512], 32);

/* ── Main ───────────────────────────────────────────────────────────── */
int main(void)
{
    /* 1. Enable clocks for DMA0 and DMAMUX0 */
    CLOCK_EnableClock(kCLOCK_Dma0);
    CLOCK_EnableClock(kCLOCK_Dmamux0);

    /* 2. Configure DMAMUX: channel 0 source = always enabled (0) */
    DMAMUX_SetSource(DMAMUX0, 0, 0);               /* source 0 = always enabled */
    DMAMUX_EnableChannel(DMAMUX0, 0);

    /* 3. Initialize eDMA */
    edma_config_t edmaConfig;
    edma_handle_t edmaHandle;

    EDMA_GetDefaultConfig(&edmaConfig);
    EDMA_Init(DMA0, &edmaConfig);
    EDMA_CreateHandle(&edmaHandle, DMA0, 0);

    /* 4. Prepare transfer descriptor (byte-wide, 512 bytes, single major loop) */
    edma_transfer_config_t xferConfig;
    EDMA_PrepareTransfer(&xferConfig,
                         (void *)src, 1,            /* srcAddr, srcWidth = 1 byte */
                         (void *)dst, 1,            /* destAddr, destWidth = 1 byte */
                         1,                         /* bytesPerRequest – single byte each request */
                         512,                       /* majorLoopBytes = 512 */
                         kEDMA_MemoryToMemory);     /* no peripheral */

    /* 5. Fill source buffer with pattern */
    for (int i = 0; i < 512; i++)
    {
        src[i] = (uint8_t)(i & 0xFF);
    }

    /* 6. Submit and start transfer */
    EDMA_SetTransferConfig(DMA0, 0, &xferConfig, NULL);
    EDMA_EnableChannel(DMA0, 0);                   /* actually enables the channel */
    EDMA_StartTransfer(DMA0, 0);                   /* triggers the transfer */

    /* 7. Wait for completion */
    while (!(EDMA_GetChannelStatusFlags(DMA0, 0) & kEDMA_TransferDoneFlag))
    {
        __NOP();
    }

    /* 8. Verify data */
    for (int i = 0; i < 512; i++)
    {
        if (dst[i] != src[i])
        {
            while (1)               /* halt on mismatch */
                ;
        }
    }

    /* 9. Done – endless loop */
    while (1)
        ;

    return 0;
}

