 * Bare-metal eDMA memory-to-memory copy for NXP i.MX RT1170
 * MCUXpresso SDK – no board files, no explicit CMSIS headers.
 * Copies 512 bytes from source to destination via DMA0 channel 0.
 * Fills source with (index & 0xFF), waits for completion, then verifies.
 */

#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_edma.h"

/* ── Buffers (aligned to 32 bytes for best DMA performance) ─────────── */
static uint8_t src[512] __attribute__((aligned(32)));
static uint8_t dst[512] __attribute__((aligned(32)));

/* ── Main ───────────────────────────────────────────────────────────── */
int main(void)
{
    /* 1. Configure DMAMUX: channel 0 source = always enabled (0x3F) */
    DMAMUX0->CHCFG[0] = 0xBF;   /* 0x3F (source) | 0x80 (ENBL) */

    /* 2. Initialize eDMA */
    edma_config_t edmaConfig;
    edma_handle_t edmaHandle;

    EDMA_GetDefaultConfig(&edmaConfig);
    EDMA_Init(DMA0, &edmaConfig);
    EDMA_CreateHandle(&edmaHandle, DMA0, 0);

    /* 3. Prepare transfer descriptor (byte-wide, 512 bytes, single major loop) */
    edma_transfer_config_t xferConfig;
    EDMA_PrepareTransfer(&xferConfig,
                         (void *)src, 1,            /* srcAddr, srcWidth = 1 byte */
                         (void *)dst, 1,            /* destAddr, destWidth = 1 byte */
                         1,                         /* bytesPerRequest – single byte each request */
                         512,                       /* majorLoopBytes = 512 */
                         kEDMA_MemoryToMemory);     /* no peripheral */

    /* 4. Fill source buffer with pattern */
    for (int i = 0; i < 512; i++)
    {
        src[i] = (uint8_t)(i & 0xFF);
    }

    /* Ensure source data is flushed from cache to memory before DMA reads it */
    SCB_CleanInvalidateDCache();

    /* 5. Submit and start transfer */
    EDMA_SubmitTransfer(&edmaHandle, &xferConfig);
    EDMA_StartTransfer(&edmaHandle);

    /* 6. Wait for completion via DONE bit in TCD CSR */
    while (!(DMA0->TCD[0].CSR & DMA_CSR_DONE_MASK))
    {
        __NOP();
    }

    /* Invalidate destination cache so CPU reads fresh data from memory */
    SCB_InvalidateDCache();

    /* 7. Verify data */
    for (int i = 0; i < 512; i++)
    {
        if (dst[i] != src[i])
        {
            while (1)               /* halt on mismatch */
                ;
        }
    }

    /* 8. Done – endless loop */
    while (1)
        ;

    return 0;
}

/*
 * Bare-metal LED blink for NXP i.MX RT1170 (Cortex-M7)
 * MCUXpresso SDK only – no board support files
 *
 * LED: GPIO9 pin 3, pad GPIO_AD_04
 * Off at startup, toggles every ~500 ms via software delay
 */

#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_gpio.h"
#include "fsl_iomuxc.h"
#include "core_cm7.h"          /* CMSIS Cortex-M7 core (SysTick not used) */

/* ----------------------------------------------------------------------------
 * Software delay – approximate. CPU frequency depends on system clock setup.
 * With default 12 MHz internal oscillator, 6e6 counts ≈ 500 ms.
 * Adjust if clock is higher (e.g., 500 MHz ~ 250e6 counts).
 * This is a rough delay, not accurate.
 */
static void delay_500ms(void)
{
    volatile uint32_t count = 6000000u;
    while (count--)
    {
        __NOP();
    }
}

/* ----------------------------------------------------------------------------
 * main – application entry
 */
int main(void)
{
    gpio_pin_config_t led_config = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = 0u   /* LED off at startup */
    };

    /* Enable clock for GPIO9 */
    CLOCK_EnableClock(kCLOCK_Gpio9);

    /* Configure IOMUXC: GPIO_AD_04 (pad) as GPIO9_IO03 */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_04, 0U);   /* GPIO mode, no alternate func */
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_04, 0U); /* leave at reset default */

    /* Initialize GPIO pin – low output (LED off) */
    GPIO_PinInit(GPIO9, 3u, &led_config);

    while (1u)
    {
        delay_500ms();
        /* Toggle LED by toggling the output data register bit */
        GPIO_PortToggle(GPIO9, 1u << 3u);
    }
}

