/*
 * i.MX RT1170 MCUXpresso SDK bare-metal example:
 * Read WHO_AM_I (0x75) from I2C sensor at address 0x68
 * using LPI2C1, pads GPIO_AD_08 (SCL) and GPIO_AD_09 (SDA)
 * with 400 kHz bus speed.
 *
 * Self-contained: uses only MCUXpresso SDK driver headers.
 * No board.h, pin_mux.h, clock_config.h, or debug console.
 */

#include <stdint.h>
#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_lpi2c.h"

/* -------------------------------------------------------------------------
 *  Pin configuration
 * ------------------------------------------------------------------------- */
static void configure_pins(void)
{
    /* Enable IOMUXC clock (needed to write IOMUX registers) */
    CLOCK_EnableClock(kCLOCK_Iomuxc);

    /* Set pin mux for LPI2C1 SCL and SDA */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_08_LPI2C1_SCL,
        0U,                           /* input on, no inverted */
        0U,                           /* software input on field not used */
        0U,                           /* daisy chain not used (direct) */
        0U,                           /* input select (none) */
        0U                            /* software input on disabled */
    );

    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_09_LPI2C1_SDA,
        0U, 0U, 0U, 0U, 0U
    );

    /* Configure pad properties:
     *   - Pull-up enabled
     *   - 100kΩ pull-up
     *   - Fast slew rate
     *   - High drive strength
     *   - Hysteresis enabled
     *   - Open drain enabled (I2C requires open drain)
     */
    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_08_LPI2C1_SCL,
        0x10B0u   /* typical I2C pad config for RT1170 */
    );

    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_09_LPI2C1_SDA,
        0x10B0u
    );
}

/* -------------------------------------------------------------------------
 *  Clock configuration
 * ------------------------------------------------------------------------- */
static void configure_clocks(void)
{
    /* Enable LPI2C1 peripheral clock gate */
    CLOCK_EnableClock(kCLOCK_Lpi2c1);

    /*
     * On i.MX RT1170 the LPI2C1 clock root defaults to 24 MHz RCOSC.
     * No need to change it for 400 kHz operation; the baud rate divider
     * will be set accordingly.
     * If a different root clock were required, use:
     *   CLOCK_SetRootClockMux(kCLOCK_Root_Lpi2c1, ...);
     *   CLOCK_SetRootClockDiv(kCLOCK_Root_Lpi2c1, ...);
     */
}

/* -------------------------------------------------------------------------
 *  Main application
 * ------------------------------------------------------------------------- */
int main(void)
{
    status_t status;
    uint8_t who_am_i = 0;               /* register read result */

    /* 1. System clock / FPU etc. not needed for this simple task */

    /* 2. Configure pins */
    configure_pins();

    /* 3. Configure clocks */
    configure_clocks();

    /* 4. Initialize LPI2C1 master */
    lpi2c_master_config_t lpi2cConfig;
    uint32_t lpi2cClockFreq;

    /* Get the current LPI2C1 root clock frequency */
    lpi2cClockFreq = CLOCK_GetRootClockFreq(kCLOCK_Root_Lpi2c1);

    /* Get default configuration and set target baud rate */
    LPI2C_MasterGetDefaultConfig(&lpi2cConfig);
    lpi2cConfig.baudRate_Bps = 400000U;

    LPI2C_MasterInit(LPI2C1, &lpi2cConfig, lpi2cClockFreq);

    /* 5. Perform I2C read: read 1 byte from subaddress 0x75 of slave 0x68 */
    lpi2c_master_transfer_t transfer;
    transfer.slaveAddress   = 0x68U;              /* 7-bit sensor address */
    transfer.direction      = kLPI2C_Read;        /* read from sensor */
    transfer.subaddress     = 0x75U;              /* WHO_AM_I register */
    transfer.subaddressSize = 1U;                 /* 1 byte subaddress */
    transfer.data           = &who_am_i;          /* store result here */
    transfer.dataSize       = 1U;                 /* read 1 byte */
    transfer.flags          = kLPI2C_TransferDefaultFlag;

    status = LPI2C_MasterTransferBlocking(LPI2C1, &transfer);

    if (status != kStatus_Success)
    {
        /* Transaction failed – could be NACK, timeout, etc.
         * For a real application, handle the error appropriately.
         */
        while (1);
    }

    /*
     * At this point, who_am_i holds the sensor's WHO_AM_I value.
     * For the MPU6050 / ICM-20600 family that value is typically 0x68 or 0x71.
     * Use as needed.
     */

    /* Infinite loop to keep result available for inspection */
    volatile uint8_t result = who_am_i;   /* mark shared variable volatile */
    (void)result;

    while (1);
}

