/**
 * bare-metal LPUART1 echo for NXP i.MX RT1170 (Cortex-M7)
 * MCUXpresso SDK — no board files, no config tools.
 *
 * Pads: GPIO_AD_24 (TXD), GPIO_AD_25 (RXD)
 * Baud: 115200, 8N1
 * Loop: read one byte, write it back immediately (polling)
 */

#include <stdint.h>
#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_lpuart.h"

/* --------------------------------------------------------------------------
 *  Clock setup — LPUART1 root clock from 24 MHz oscillator (source 0)
 * -------------------------------------------------------------------------- */
static void BOARD_InitClocks(void)
{
    /* Enable LPUART1 clock gate */
    CLOCK_EnableClock(kCLOCK_Lpuart1);

    /* Configure LPUART1 root clock:
     *   mux = 0  → 24 MHz (from OSC or PLL – check RM for your platform)
     *   div = 1  → output = 24 MHz
     */
    CLOCK_SetRootClockMux(kCLOCK_Root_Lpuart1, 0);
    CLOCK_SetRootClockDivider(kCLOCK_Root_Lpuart1, 1);
}

/* --------------------------------------------------------------------------
 *  Pin mux — LPUART1 on GPIO_AD_24 (TX) / GPIO_AD_25 (RX)
 *  Mux mode: ALT2 (LPUART1_TXD / LPUART1_RXD)
 * -------------------------------------------------------------------------- */
static void BOARD_InitPins(void)
{
    /* Set mux mode */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_24_LPUART1_TXD, 0);
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_25_LPUART1_RXD, 0);

    /* Configure pad electrical settings (example: 100R pull, fast slew, high drive)
     * Refer to RM for exact bit fields; 0x10B0 is a common safe choice. */
    const uint32_t pad_config = (IOMUXC_PAD_SLEW_FAST |
                                 IOMUXC_PAD_DRIVE_HIGH |
                                 IOMUXC_PAD_PULL_ENABLE |
                                 IOMUXC_PAD_PULL_UP_100K);
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_24_LPUART1_TXD, pad_config);
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_25_LPUART1_RXD, pad_config);
}

/* --------------------------------------------------------------------------
 *  LPUART1 initialisation – 115200 baud, 8N1
 * -------------------------------------------------------------------------- */
static void BOARD_InitUART(void)
{
    lpuart_config_t config;
    uint32_t uart_clock;

    /* Get default config (8N1, oversampling ratio 16) */
    LPUART_GetDefaultConfig(&config);
    config.baudRate_Bps = 115200;
    config.enableTx     = true;
    config.enableRx     = true;

    /* Retrieve actual root clock frequency (should be 24 MHz) */
    uart_clock = CLOCK_GetRootClockFreq(kCLOCK_Root_Lpuart1);

    /* Initialize LPUART1 */
    LPUART_Init(LPUART1, &config, uart_clock);

    /* Enable data buffers (FIFO) – optional but recommended */
    LPUART_EnableTx(LPUART1, true);
    LPUART_EnableRx(LPUART1, true);
}

/* --------------------------------------------------------------------------
 *  main – echo loop
 * -------------------------------------------------------------------------- */
int main(void)
{
    /* Initialise everything */
    BOARD_InitClocks();
    BOARD_InitPins();
    BOARD_InitUART();

    while (1)
    {
        /* Wait until a byte has been received */
        while (!(LPUART_GetStatusFlags(LPUART1, kLPUART_RxDataRegFullFlag)))
        {
            __NOP();
        }
        uint8_t data = LPUART_ReadByte(LPUART1);

        /* Wait until the transmit data register is empty */
        while (!(LPUART_GetStatusFlags(LPUART1, kLPUART_TxDataRegEmptyFlag)))
        {
            __NOP();
        }
        LPUART_WriteByte(LPUART1, data);
    }
}

